// Package repository is the PostgreSQL adapter of the notifications domain (queries generated by sqlc).
package repository

import (
	"context"
	"encoding/json"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/quixgit/greenops-reliabilix/backend/internal/notifications/domain"
	"github.com/quixgit/greenops-reliabilix/backend/internal/notifications/repository/db"
	"github.com/quixgit/greenops-reliabilix/backend/internal/platform/audit"
	"github.com/quixgit/greenops-reliabilix/backend/internal/platform/database"
	"github.com/quixgit/greenops-reliabilix/backend/internal/platform/notify"
)

type Postgres struct{ Pool *pgxpool.Pool }

var _ domain.Repository = Postgres{}

func destToDomain(x db.NotificationsDestination) domain.Destination {
	return domain.Destination{ID: x.ID, Kind: domain.Kind(x.Kind), Name: x.Name, Hint: x.TargetHint, EventTypes: x.EventTypes,
		MinSeverity: notify.Severity(x.MinSeverity), Enabled: x.Enabled, CreatedBy: x.CreatedBy, CreatedAt: x.CreatedAt, SealedTarget: x.TargetSealed}
}

func (r Postgres) CountDestinations(ctx context.Context, tenantID string) (n int, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		c, err := db.New(tx).CountDestinations(ctx, tenantID)
		n = int(c)
		return err
	})
	return
}

func (r Postgres) InsertDestination(ctx context.Context, tenantID string, d domain.Destination) (out domain.Destination, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		x, err := db.New(tx).InsertDestination(ctx, db.InsertDestinationParams{ID: d.ID, TenantID: tenantID, Kind: string(d.Kind), Name: d.Name,
			TargetSealed: d.SealedTarget, TargetHint: d.Hint, EventTypes: d.EventTypes, MinSeverity: string(d.MinSeverity), Enabled: d.Enabled, CreatedBy: d.CreatedBy})
		if err != nil {
			return err
		}
		out = destToDomain(db.NotificationsDestination(x))
		// The address is secret: the audit entry carries the kind and the masked hint only.
		return audit.Record(ctx, tx, "notification_destination.created", "destination:"+out.ID, map[string]any{"kind": out.Kind, "target": out.Hint})
	})
	return
}

func (r Postgres) ListDestinations(ctx context.Context, tenantID string) (out []domain.Destination, err error) {
	out = []domain.Destination{}
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := db.New(tx).ListDestinations(ctx, tenantID)
		for _, x := range rows {
			out = append(out, destToDomain(db.NotificationsDestination(x)))
		}
		return err
	})
	return
}

func (r Postgres) GetDestination(ctx context.Context, tenantID, id string) (d domain.Destination, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		x, err := db.New(tx).GetDestination(ctx, db.GetDestinationParams{TenantID: tenantID, ID: id})
		if database.IsNotFound(err) {
			return domain.ErrNotFound
		}
		d = destToDomain(db.NotificationsDestination(x))
		return err
	})
	return
}

func (r Postgres) SetEnabled(ctx context.Context, tenantID, id string, enabled bool) (d domain.Destination, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		x, err := db.New(tx).SetDestinationEnabled(ctx, db.SetDestinationEnabledParams{TenantID: tenantID, ID: id, Enabled: enabled})
		if database.IsNotFound(err) {
			return domain.ErrNotFound
		}
		if err != nil {
			return err
		}
		d = destToDomain(db.NotificationsDestination(x))
		action := "notification_destination.disabled"
		if enabled {
			action = "notification_destination.enabled"
		}
		return audit.Record(ctx, tx, action, "destination:"+id, nil)
	})
	return
}

func (r Postgres) DeleteDestination(ctx context.Context, tenantID, id string) error {
	return database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		n, err := db.New(tx).DeleteDestination(ctx, db.DeleteDestinationParams{TenantID: tenantID, ID: id})
		if err != nil {
			return err
		}
		if n == 0 {
			return domain.ErrNotFound
		}
		return audit.Record(ctx, tx, "notification_destination.deleted", "destination:"+id, nil)
	})
}

func (r Postgres) InsertDeliveries(ctx context.Context, tenantID string, ds []domain.Destination, e notify.Event) (ids []string, err error) {
	payload, err := json.Marshal(e)
	if err != nil {
		return nil, err
	}
	var key *string
	if e.DedupeKey != "" {
		key = &e.DedupeKey
	}
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		q := db.New(tx)
		for _, d := range ds {
			id, err := q.InsertDelivery(ctx, db.InsertDeliveryParams{TenantID: tenantID, DestinationID: &d.ID, Kind: string(d.Kind), DestinationName: d.Name,
				EventType: e.Type, Severity: string(e.Severity), Payload: payload, DedupeKey: key})
			if database.IsNotFound(err) {
				continue // already delivered or queued for this destination
			}
			if err != nil {
				return err
			}
			ids = append(ids, id)
		}
		return nil
	})
	return
}

func deliveryToDomain(x db.ListDeliveriesRow) domain.Delivery {
	return domain.Delivery{ID: x.ID, DestinationID: x.DestinationID, Kind: domain.Kind(x.Kind), DestinationName: x.DestinationName, EventType: x.EventType,
		Severity: notify.Severity(x.Severity), Status: domain.Status(x.Status), Attempts: int(x.Attempts), NextAttemptAt: x.NextAttemptAt,
		LastError: x.LastError, CreatedAt: x.CreatedAt, SentAt: x.SentAt}
}

func (r Postgres) ListDeliveries(ctx context.Context, tenantID string, limit int) (out []domain.Delivery, err error) {
	out = []domain.Delivery{}
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := db.New(tx).ListDeliveries(ctx, db.ListDeliveriesParams{TenantID: tenantID, RowLimit: int32(min(max(limit, 1), 1000))})
		for _, x := range rows {
			out = append(out, deliveryToDomain(x))
		}
		return err
	})
	return
}

func (r Postgres) Claim(ctx context.Context, tenantID, deliveryID string, lease time.Duration) (d domain.Delivery, dest *domain.Destination, ok bool, err error) {
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		q := db.New(tx)
		x, err := q.ClaimDelivery(ctx, db.ClaimDeliveryParams{TenantID: tenantID, ID: deliveryID, LeaseSecs: lease.Seconds()})
		if database.IsNotFound(err) {
			return nil
		}
		if err != nil {
			return err
		}
		ok = true
		d = deliveryToDomain(db.ListDeliveriesRow{ID: x.ID, DestinationID: x.DestinationID, Kind: x.Kind, DestinationName: x.DestinationName, EventType: x.EventType,
			Severity: x.Severity, Status: x.Status, Attempts: x.Attempts, NextAttemptAt: x.NextAttemptAt, LastError: x.LastError, CreatedAt: x.CreatedAt, SentAt: x.SentAt})
		if err := json.Unmarshal(x.Payload, &d.Event); err != nil {
			return err
		}
		if x.DestinationID != nil {
			dx, err := q.GetDestination(ctx, db.GetDestinationParams{TenantID: tenantID, ID: *x.DestinationID})
			if err != nil && !database.IsNotFound(err) {
				return err
			}
			if err == nil {
				dd := destToDomain(db.NotificationsDestination(dx))
				dest = &dd
			}
		}
		return nil
	})
	return
}

func (r Postgres) MarkSent(ctx context.Context, tenantID, deliveryID string) error {
	return database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		return db.New(tx).MarkDeliverySent(ctx, db.MarkDeliverySentParams{TenantID: tenantID, ID: deliveryID})
	})
}

func (r Postgres) MarkRetry(ctx context.Context, tenantID, deliveryID string, next time.Time, reason string) error {
	return database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		return db.New(tx).MarkDeliveryRetry(ctx, db.MarkDeliveryRetryParams{TenantID: tenantID, ID: deliveryID, NextAttemptAt: next, LastError: &reason})
	})
}

func (r Postgres) MarkFailed(ctx context.Context, tenantID, deliveryID string, status domain.Status, reason string) error {
	return database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		if err := db.New(tx).MarkDeliveryFinal(ctx, db.MarkDeliveryFinalParams{TenantID: tenantID, ID: deliveryID, Status: string(status), LastError: &reason}); err != nil {
			return err
		}
		if status != domain.Failed {
			return nil
		}
		return audit.Record(audit.WithTenant(ctx, tenantID), tx, "notification.delivery_failed", "delivery:"+deliveryID, map[string]any{"reason": reason})
	})
}

func (r Postgres) ListDue(ctx context.Context, limit int) ([]domain.DueRef, error) {
	rows, err := r.Pool.Query(ctx, `SELECT tenant_id::text, id::text FROM notifications.list_due_deliveries($1)`, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []domain.DueRef
	for rows.Next() {
		var d domain.DueRef
		if err := rows.Scan(&d.TenantID, &d.DeliveryID); err != nil {
			return nil, err
		}
		out = append(out, d)
	}
	return out, rows.Err()
}

func (r Postgres) Purge(ctx context.Context, retain time.Duration) (n int64, err error) {
	err = r.Pool.QueryRow(ctx, `SELECT notifications.purge_old_deliveries(make_interval(secs => $1::float8))`, retain.Seconds()).Scan(&n)
	return
}
